long long solve(const long long *values, int n) {
  if (n <= 0) return 0;
  long long *afloat = (long long *)malloc(sizeof(long long) * (size_t)n);
  int top = 0;
  for (int i = 0; i < n; i++) {
    long long floe = values[i];
    int alive = 1;
    while (alive && top > 0 && afloat[top - 1] > 0 && floe < 0) {
      long long westbound = -floe;
      if (afloat[top - 1] < westbound) {
        top--;
      } else if (afloat[top - 1] == westbound) {
        top--;
        alive = 0;
      } else {
        alive = 0;
      }
    }
    if (alive) afloat[top++] = floe;
  }
  free(afloat);
  return (long long)top;
}

